69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
73	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
74	     * and a dotted domain (e.g. {@code not-an-email}).
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
77	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
78	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
79	
80	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
81	    private static final String DEFAULT_COUNTRY_CODE = "61";
82	
83	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
84	    private static final int MAX_OWNERS_PER_CITY = 50;
85	
86	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
87	    private static final int MAX_OWNERS_PER_DAY = 100;
88	
89	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
90	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
91	
92	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
93	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
94	
95	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
96	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
97	
98	    /**
99	     * Country calling codes with a fixed national-number length. An E.164 number whose country code
100	     * is listed here must carry exactly the required number of national digits, otherwise it is
101	     * rejected ({@code +61} requires 9 national digits, {@code +1} requires 10). Ordered so that a
102	     * longer prefix is matched before a shorter one (e.g. {@code 61} before {@code 1}).
103	     */
104	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of(
105	        "61", 9,
106	        "1", 10);
107	
108	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
109	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
110	        "ST", "STREET",
111	        "RD", "ROAD",
112	        "AVE", "AVENUE");
113	
114	    /** A well-formed postcode: exactly four digits. */
115	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
116	
117	    /** City to canonical region for the fixed city-to-region table (cities not listed have no region). */
118	    private static final Map<String, String> CITY_REGION = Map.of(
119	        "Sydney", "NSW",
120	        "Melbourne", "VIC",
121	        "Brisbane", "QLD");
122	
123	    /** Region to its inclusive 4-digit postcode range {low, high}. */
124	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
125	        "NSW", new int[] {2000, 2099},
126	        "VIC", new int[] {3000, 3099},
127	        "QLD", new int[] {4000, 4099});
128	
129	    /** Dedicated audit logger; a create side-effect is recorded here on success. */
130	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
131	
