177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
180	        List<String> missingFields = new ArrayList<>();
181	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
182	            missingFields.add("firstName");
183	        }
184	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
185	            missingFields.add("lastName");
186	        }
187	        // Normalize the address up front; the required-field check rejects it when it is blank
188	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
189	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
190	        if (!StringUtils.hasText(normalizedAddress)) {
191	            missingFields.add("address");
192	        }
193	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
194	            missingFields.add("city");
195	        }
196	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
197	            missingFields.add("telephone");
198	        }
199	        if (!missingFields.isEmpty()) {
200	            throw new InvalidRequestException(missingFields);
201	        }
202	        HttpHeaders headers = new HttpHeaders();
203	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
204	        // Store (and later return) the normalized address computed above.
205	        owner.setAddress(normalizedAddress);
206	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
207	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
208	        owner.setTelephone(normalizedTelephone);
209	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
210	        owner.setEmail(normalizeEmail(owner.getEmail()));
211	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
212	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
213	        validatePostcode(owner.getCity(), owner.getPostcode());
214	        // Reject a supplied registration date that lies in the future (later than the server's current
215	        // date) with a 400 Bad Request. Checked against the raw supplied value, before defaulting below.
216	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
217	            throw new InvalidRequestException(List.of("registrationDate"));
218	        }
219	        // Default the (optional) registration date to the server's current date when none was supplied.
220	        if (owner.getRegistrationDate() == null) {
221	            owner.setRegistrationDate(LocalDate.now());
222	        }
223	        // The effective registration date must fall on a business day: when it lands on a Saturday or
224	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
225	        // derived from the registration date below (daily create-limit, membership number) uses this
226	        // adjusted date.
227	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
228	        // Reject the request once the maximum number of owners for the owner's registration day has
229	        // been reached (100 or more owners already created on that date).
230	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
231	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
232	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
233	        }
234	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
235	        // owner's registration day at the moment this owner was created; otherwise clear it.
236	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
237	        // Reject the request when the owner's city has already reached its owner capacity.
238	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
239	            throw new CityCapacityException(owner.getCity());
240	        }
241	        // Resolve household membership before computing the identity key: when another owner already
242	        // shares the same last name and address (compared case-insensitively with collapsed
243	        // whitespace) and the caller opts in by setting 'sharesHousehold' true, assign a stable
244	        // shared 'householdId' to the new owner and backfill it onto every existing member that does
245	        // not yet carry it. The household is thus reflected in the owner's identity key.
246	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
247	        if (!householdMembers.isEmpty() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
248	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
249	            owner.setHouseholdId(householdId);
250	            for (Owner member : householdMembers) {
251	                if (!householdId.equals(member.getHouseholdId())) {
252	                    member.setHouseholdId(householdId);
253	                    this.clinicService.saveOwner(member);
254	                }
255	            }
256	        }
257	        // All duplicate detection is consolidated into this single derived identity key
258	        // ('<normalizedTelephone>|<email or empty>|<householdId or empty>'): reject with 409 only
259	        // when the new owner's WHOLE identity key exactly matches an existing owner's. Because the
260	        // telephone is part of the key, two members of the same household with different telephones
261	        // have different keys and are both allowed; only an exact full-key match is a duplicate.
262	        String identityKey = owner.getIdentityKey();
263	        boolean identityCollision = this.clinicService.findAllOwners().stream()
264	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
265	        if (identityCollision) {
266	            throw new DuplicateIdentityException(identityKey);
267	        }
268	        // Soft-match detection: the new owner is not a hard (identity-key) duplicate, but it may
269	        // still be a likely duplicate of an existing owner. Flag it when an existing owner shares
270	        // this owner's last name (compared case-insensitively with collapsed whitespace) and
271	        // postcode while carrying a DIFFERENT normalized telephone. When several existing owners
272	        // match, the one with the lowest id is chosen so the result is deterministic.
273	        Owner softMatch = findPossibleDuplicate(owner);
274	        if (softMatch != null) {
275	            owner.setPossibleDuplicate(true);
276	            owner.setPossibleDuplicateOf(softMatch.getId());
277	        } else {
278	            owner.setPossibleDuplicate(false);
279	        }
280	        // Record how many existing owners already share this first name and last name
281	        // (compared case-insensitively) before this owner is created.
282	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
283	        // Assign the customer code '<REGION>-<HASH8>' before persisting.
284	        owner.setCustomerCode(generateCustomerCode(owner));
285	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
286	        // digits of the registration date year (e.g. 'NSW-1A2B3C4D-M26').
287	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
288	        this.clinicService.saveOwner(owner);
289	        populateHouseholdSize(owner);
290	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
291	        // Emit an audit line carrying the new owner's id, customer code, registration date
292	        // and numeric membership level.
293	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
294	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
295	            ownerDto.getMembershipLevel());
296	        headers.setLocation(UriComponentsBuilder.newInstance()
297	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
298	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
299	    }
300	
301	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
302	    @Override
303	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
304	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
305	        if (currentOwner == null) {
306	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
307	        }
308	        currentOwner.setAddress(ownerFieldsDto.getAddress());
309	        currentOwner.setCity(ownerFieldsDto.getCity());
310	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
311	        currentOwner.setLastName(ownerFieldsDto.getLastName());
312	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
313	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
314	        this.clinicService.saveOwner(currentOwner);
315	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
316	    }
