318	    /**
319	     * Populate the owner's household size: the number of owners sharing this owner's
320	     * {@code householdId} (including the owner itself). An owner with no household is a household
321	     * of one.
322	     *
323	     * @param owner the owner whose household size should be computed and set
324	     */
325	    private void populateHouseholdSize(Owner owner) {
326	        String householdId = owner.getHouseholdId();
327	        if (!StringUtils.hasText(householdId)) {
328	            owner.setHouseholdSize(1);
329	            return;
330	        }
331	        int size = (int) this.clinicService.findAllOwners().stream()
332	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
333	            .count();
334	        owner.setHouseholdSize(size);
335	    }
336	
337	    /**
338	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
339	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
340	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
341	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
342	     * longer any per-city sequence number.
343	     *
344	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
345	     * @return the generated customer code
346	     */
347	    private String generateCustomerCode(Owner owner) {
348	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
349	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
350	        return region + "-" + hash8;
351	    }
352	
353	    /**
354	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
355	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
356	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
357	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
358	     * known region.
359	     *
360	     * @param postcode the owner's postcode, may be {@code null}
361	     * @param city     the owner's city
362	     * @return the derived region code
363	     */
364	    private String deriveRegion(String postcode, String city) {
365	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
366	            int value = Integer.parseInt(postcode);
367	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
368	                int[] range = entry.getValue();
369	                if (value >= range[0] && value <= range[1]) {
370	                    return entry.getKey();
371	                }
372	            }
373	        }
374	        String region = CITY_REGION.get(city);
375	        return region != null ? region : "UNKNOWN";
376	    }
377	
378	    /**
379	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
380	     * bytes of {@code input}.
381	     *
382	     * @param input  the value to digest
383	     * @param length the number of leading hex characters to return
384	     * @return the truncated upper-case hex digest
385	     */
386	    private String shortSha256Hex(String input, int length) {
387	        try {
388	            byte[] digest = MessageDigest.getInstance("SHA-256")
389	                .digest(input.getBytes(StandardCharsets.UTF_8));
390	            StringBuilder sb = new StringBuilder(digest.length * 2);
391	            for (byte b : digest) {
392	                sb.append(String.format("%02x", b));
393	            }
394	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
395	        } catch (java.security.NoSuchAlgorithmException e) {
396	            throw new IllegalStateException("SHA-256 not available", e);
397	        }
398	    }
399	
400	    /**
401	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
402	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
403	     * that is stored, returned and used for every value derived from it.
404	     *
405	     * @param date the effective registration date (supplied or defaulted)
406	     * @return the same date when it is a weekday, otherwise the next Monday
407	     */
408	    private LocalDate rollToBusinessDay(LocalDate date) {
409	        DayOfWeek dayOfWeek = date.getDayOfWeek();
410	        if (dayOfWeek == DayOfWeek.SATURDAY) {
411	            return date.plusDays(2);
412	        }
413	        if (dayOfWeek == DayOfWeek.SUNDAY) {
414	            return date.plusDays(1);
415	        }
416	        return date;
417	    }
418	
419	    /**
420	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
421	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
422	     *
423	     * @param customerCode     the owner's already-assigned customer code
424	     * @param registrationDate the owner's registration date
425	     * @return the generated membership number
426	     */
427	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
428	        String yy = String.format("%02d", registrationDate.getYear() % 100);
429	        return String.format("%s-M%s", customerCode, yy);
430	    }
431	
432	    /**
433	     * Count the existing owners that share the given first name and last name, comparing each
434	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
435	     * yet persisted, so it is not included in the count.
436	     *
437	     * @param firstName the incoming owner's first name
438	     * @param lastName  the incoming owner's last name
439	     * @return the number of existing namesakes
440	     */
441	    private int countNamesakes(String firstName, String lastName) {
442	        String normalizedFirstName = normalizeForComparison(firstName);
443	        String normalizedLastName = normalizeForComparison(lastName);
444	        return (int) this.clinicService.findAllOwners().stream()
445	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
446	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
447	            .count();
448	    }
449	
450	    /**
451	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
452	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
453	     *
454	     * @param city the incoming owner's city
455	     * @return the number of existing owners already in that city
456	     */
457	    private int countOwnersInCity(String city) {
458	        String normalizedCity = normalizeForComparison(city);
459	        return (int) this.clinicService.findAllOwners().stream()
460	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
461	            .count();
462	    }
463	
464	    /**
465	     * Count the existing owners whose registration date equals the given date. The incoming owner is
466	     * not yet persisted, so it is not included in the count.
467	     *
468	     * @param registrationDate the incoming owner's registration date
469	     * @return the number of existing owners already registered on that date
470	     */
471	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
472	        return (int) this.clinicService.findAllOwners().stream()
473	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
474	            .count();
475	    }
476	
477	    /**
478	     * Find the existing owners that live in the same household as the given values, i.e. those that
479	     * share both the last name and the address when each is compared case-insensitively with
480	     * collapsed whitespace.
481	     *
482	     * @param lastName the incoming owner's last name
483	     * @param address  the incoming owner's address
484	     * @return the matching existing owners (possibly empty)
485	     */
486	    private List<Owner> findHouseholdMembers(String lastName, String address) {
487	        String normalizedLastName = normalizeForComparison(lastName);
488	        String normalizedAddress = normalizeForComparison(address);
489	        return this.clinicService.findAllOwners().stream()
490	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
491	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
492	            .toList();
493	    }
494	
495	    /**
496	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
497	     * shares the owner's last name (compared case-insensitively with collapsed whitespace) and
498	     * postcode while carrying a different normalized telephone. A blank postcode never soft-matches
499	     * (postcode is required for the match). When several owners match, the one with the lowest id is
500	     * returned so the result is deterministic; {@code null} when there is no soft match.
501	     *
502	     * @param owner the incoming owner (with normalized telephone and last name resolved)
503	     * @return the lowest-id matching existing owner, or {@code null} when none matches
504	     */
505	    private Owner findPossibleDuplicate(Owner owner) {
506	        if (!StringUtils.hasText(owner.getPostcode())) {
507	            return null;
508	        }
509	        String normalizedLastName = normalizeForComparison(owner.getLastName());
510	        String telephone = owner.getTelephone();
511	        return this.clinicService.findAllOwners().stream()
512	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
513	                && owner.getPostcode().equals(existing.getPostcode())
514	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
515	            .min(java.util.Comparator.comparing(Owner::getId))
516	            .orElse(null);
517	    }
518	
519	    /**
520	     * Generate a stable shared household identifier for the given last name and address. The value is
521	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
522	     * and address, so every owner joining the same household resolves to the same identifier. It is the
523	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
524	     *
525	     * @param lastName the household's last name
526	     * @param address  the household's address
527	     * @return the stable household identifier
528	     */
529	    private String generateHouseholdId(String lastName, String address) {
530	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
531	        return shortSha256Hex(key, 12);
532	    }
533	
534	    /**
535	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
536	     * single space, upper-case the result and expand common street-type abbreviations token by token
537	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
538	     * to the empty string. The result is the canonical form that is stored, returned and used for every
539	     * address comparison (household duplicate detection and the shared household id).
540	     *
541	     * @param address the raw address, may be {@code null}
542	     * @return the normalized address
543	     */
544	    private String normalizeAddress(String address) {
545	        if (address == null) {
546	            return "";
547	        }
548	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
549	        if (collapsed.isEmpty()) {
550	            return "";
551	        }
552	        String[] tokens = collapsed.split(" ");
553	        StringBuilder sb = new StringBuilder(collapsed.length());
554	        for (int i = 0; i < tokens.length; i++) {
555	            if (i > 0) {
556	                sb.append(' ');
557	            }
558	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
559	        }
560	        return sb.toString();
561	    }
562	
563	    /**
564	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
565	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
566	     *
567	     * @param value the raw value, may be {@code null}
568	     * @return the normalized value
569	     */
570	    private String normalizeForComparison(String value) {
571	        if (value == null) {
572	            return "";
573	        }
574	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
575	    }
576	
577	    /**
578	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
579	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
580	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
581	     * is returned lower-cased.
582	     *
583	     * @param email the raw email from the request payload, may be {@code null}
584	     * @return the lower-cased email, or {@code null} when none was provided
585	     */
586	    private String normalizeEmail(String email) {
587	        if (!StringUtils.hasText(email)) {
588	            return null;
589	        }
590	        if (!EMAIL_PATTERN.matcher(email).matches()) {
591	            throw new InvalidRequestException(List.of("email"));
592	        }
593	        return email.toLowerCase(Locale.ROOT);
594	    }
595	
596	    /**
597	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
598	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
599	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
600	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
601	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
602	     * to 400 Bad Request).
603	     *
604	     * @param city     the owner's city (used to resolve the region)
605	     * @param postcode the raw postcode from the request payload, may be {@code null}
606	     */
607	    private void validatePostcode(String city, String postcode) {
608	        if (!StringUtils.hasText(postcode)) {
609	            return;
610	        }
611	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
612	            throw new InvalidRequestException(List.of("postcode"));
613	        }
614	        String region = CITY_REGION.get(city);
615	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
616	        if (range != null) {
617	            int value = Integer.parseInt(postcode);
618	            if (value < range[0] || value > range[1]) {
619	                throw new InvalidRequestException(List.of("postcode"));
620	            }
621	        }
622	    }
623	
624	    /**
625	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
626	     * already carries a leading '+' keeps its country code; otherwise the default country code
627	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
628	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
629	     * is thrown (mapped to 400 Bad Request).
630	     *
631	     * @param telephone the raw telephone from the request payload
632	     * @return the E.164 string (e.g. {@code +61412345678})
633	     */
634	    private String normalizeTelephone(String telephone) {
635	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
636	        String candidate;
637	        if (cleaned.startsWith("+")) {
638	            candidate = cleaned;
639	        } else {
640	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
641	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
642	        }
643	        if (!E164_PATTERN.matcher(candidate).matches()) {
644	            throw new InvalidRequestException(List.of("telephone"));
645	        }
646	        // For country codes with a known fixed national-number length, reject a candidate whose
647	        // national digits (everything after the '+' and the country code) do not match that length.
648	        String digits = candidate.substring(1);
649	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
650	            String countryCode = entry.getKey();
651	            if (digits.startsWith(countryCode)) {
652	                int nationalLength = digits.length() - countryCode.length();
653	                if (nationalLength != entry.getValue()) {
654	                    throw new InvalidRequestException(List.of("telephone"));
655	                }
656	                break;
657	            }
658	        }
659	        return candidate;
660	    }
661	
662	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
663	    @Transactional
664	    @Override
665	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
666	        Owner owner = this.clinicService.findOwnerById(ownerId);
667	        if (owner == null) {
668	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
669	        }
670	        this.clinicService.deleteOwner(owner);
671	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
672	    }
673	
674	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
675	    @Override
676	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
677	        Owner owner = this.clinicService.findOwnerById(ownerId);
678	        if (owner == null) {
679	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
680	        }
681	        HttpHeaders headers = new HttpHeaders();
682	        Pet pet = petMapper.toPet(petFieldsDto);
683	        owner.setId(ownerId);
684	        pet.setOwner(owner);
685	        pet.getType().setName(null);
686	        this.clinicService.savePet(pet);
687	        PetDto petDto = petMapper.toPetDto(pet);
688	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
689	            .buildAndExpand(pet.getId()).toUri());
690	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
691	    }
692	
693	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
694	    @Override
695	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
696	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
697	        if (currentOwner != null) {
698	            Pet currentPet = this.clinicService.findPetById(petId);
699	            if (currentPet != null) {
700	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
701	                currentPet.setName(petFieldsDto.getName());
702	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
703	                this.clinicService.savePet(currentPet);
704	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
705	            }
706	        }
707	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
708	    }
709	
710	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
711	    @Override
712	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
713	        HttpHeaders headers = new HttpHeaders();
714	        Visit visit = visitMapper.toVisit(visitFieldsDto);
715	        Pet pet = new Pet();
716	        pet.setId(petId);
717	        visit.setPet(pet);
718	        this.clinicService.saveVisit(visit);
719	        VisitDto visitDto = visitMapper.toVisitDto(visit);
720	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
721	            .buildAndExpand(visit.getId()).toUri());
722	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
723	    }
724	
725	
726	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
727	    @Override
728	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
729	        Owner owner = this.clinicService.findOwnerById(ownerId);
730	        if (owner != null) {
731	            Pet pet = owner.getPet(petId);
732	            if (pet != null) {
733	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
734	            }
735	        }
736	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
737	    }
738	}
